CREATE TABLE IF NOT EXISTS item_restrictions(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,restriction_kind VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,item_code VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NULL,display_name VARCHAR(191) NOT NULL,reason VARCHAR(500) NULL,source_order BIGINT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uq_item_restriction_order(restriction_kind,source_order),UNIQUE KEY uq_item_restriction_name(restriction_kind,display_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
